namespace BillingService.Events;
public class ServiceCompletedEvent { public Guid EventId { get; set; } public string EventType { get; set; } = string.Empty; public DateTime OccurredAt { get; set; } public string Source { get; set; } = string.Empty; public string? CorrelationId { get; set; } public ServiceCompletedData Data { get; set; } = new(); }
public class ServiceCompletedData { public int JobCardId { get; set; } public string JobCardNumber { get; set; } = string.Empty; public int CustomerId { get; set; } public int VehicleId { get; set; } public string VehicleRegistrationNumber { get; set; } = string.Empty; }
